CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '' CHECK(length(display_name)<=100), college text NOT NULL DEFAULT '' CHECK(length(college)<=150), skills text[] NOT NULL DEFAULT '{}', interests text[] NOT NULL DEFAULT '{}');
GRANT SELECT,INSERT,UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role; ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_profile ON public.profiles FOR ALL TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE FUNCTION public.create_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES(NEW.id,left(coalesce(NEW.raw_user_meta_data->>'display_name',''),100)); RETURN NEW; END $$;
CREATE TRIGGER on_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_profile();
CREATE TABLE public.user_roles(user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE, role text CHECK(role IN ('admin','organizer')), PRIMARY KEY(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role; ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_role ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.is_organizer() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role IN ('admin','organizer')) $$;
CREATE TABLE public.events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text UNIQUE NOT NULL, title text NOT NULL CHECK(length(title) BETWEEN 1 AND 150), category text NOT NULL, description text NOT NULL, venue text NOT NULL, starts_at timestamptz NOT NULL, deadline timestamptz NOT NULL, capacity integer NOT NULL CHECK(capacity>0), team_min integer NOT NULL DEFAULT 1, team_max integer NOT NULL DEFAULT 1 CHECK(team_max>=team_min AND team_max<=10), prize text NOT NULL DEFAULT '', rules text NOT NULL DEFAULT '', eligibility text NOT NULL DEFAULT 'All college students', contact text NOT NULL DEFAULT '', questions jsonb NOT NULL DEFAULT '[]', status text NOT NULL DEFAULT 'open' CHECK(status IN ('draft','open','closed','cancelled')), is_demo boolean NOT NULL DEFAULT false);
GRANT SELECT ON public.events TO anon,authenticated; GRANT INSERT,UPDATE,DELETE ON public.events TO authenticated; GRANT ALL ON public.events TO service_role; ALTER TABLE public.events ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_events ON public.events FOR SELECT TO anon,authenticated USING(status<>'draft'); CREATE POLICY organizer_events ON public.events FOR ALL TO authenticated USING(public.is_organizer()) WITH CHECK(public.is_organizer());
CREATE TABLE public.teams(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_id uuid NOT NULL REFERENCES public.events(id), leader_id uuid NOT NULL REFERENCES public.profiles(id), name text NOT NULL CHECK(length(name) BETWEEN 2 AND 80), looking_for text[] NOT NULL DEFAULT '{}', description text NOT NULL DEFAULT '' CHECK(length(description)<=1000), is_open boolean NOT NULL DEFAULT true, UNIQUE(event_id,name));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.teams TO authenticated; GRANT ALL ON public.teams TO service_role; ALTER TABLE public.teams ENABLE ROW LEVEL SECURITY;
CREATE POLICY teams_read ON public.teams FOR SELECT TO authenticated USING(is_open OR leader_id=auth.uid() OR public.is_organizer()); CREATE POLICY teams_own ON public.teams FOR INSERT TO authenticated WITH CHECK(leader_id=auth.uid()); CREATE POLICY teams_edit ON public.teams FOR UPDATE TO authenticated USING(leader_id=auth.uid()) WITH CHECK(leader_id=auth.uid());
CREATE TABLE public.registrations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_id uuid NOT NULL REFERENCES public.events(id), owner_id uuid NOT NULL REFERENCES public.profiles(id), team_id uuid REFERENCES public.teams(id), created_at timestamptz NOT NULL DEFAULT now(), answers jsonb NOT NULL DEFAULT '{}', UNIQUE(event_id,owner_id));
GRANT SELECT ON public.registrations TO authenticated; GRANT ALL ON public.registrations TO service_role; ALTER TABLE public.registrations ENABLE ROW LEVEL SECURITY; CREATE POLICY registration_read ON public.registrations FOR SELECT TO authenticated USING(owner_id=auth.uid() OR public.is_organizer());
CREATE TABLE public.passes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), token uuid UNIQUE NOT NULL DEFAULT gen_random_uuid(), registration_id uuid NOT NULL REFERENCES public.registrations(id), event_id uuid NOT NULL REFERENCES public.events(id), owner_id uuid NOT NULL REFERENCES public.profiles(id), participant text NOT NULL CHECK(length(participant) BETWEEN 1 AND 100), email text NOT NULL CHECK(length(email)<=255), team_id uuid REFERENCES public.teams(id), role text NOT NULL DEFAULT 'Participant', cancelled boolean NOT NULL DEFAULT false, UNIQUE(event_id,email));
GRANT SELECT ON public.passes TO authenticated; GRANT ALL ON public.passes TO service_role; ALTER TABLE public.passes ENABLE ROW LEVEL SECURITY;
CREATE POLICY passes_read ON public.passes FOR SELECT TO authenticated USING(owner_id=auth.uid() OR lower(email)=lower(auth.jwt()->>'email') OR public.is_organizer());
CREATE TABLE public.team_members(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), team_id uuid NOT NULL REFERENCES public.teams(id), user_id uuid REFERENCES public.profiles(id), display_name text NOT NULL, UNIQUE(team_id,user_id));
GRANT SELECT ON public.team_members TO authenticated; GRANT ALL ON public.team_members TO service_role; ALTER TABLE public.team_members ENABLE ROW LEVEL SECURITY; CREATE POLICY members_read ON public.team_members FOR SELECT TO authenticated USING(user_id=auth.uid() OR EXISTS(SELECT 1 FROM public.teams WHERE teams.id=team_id AND leader_id=auth.uid()) OR public.is_organizer());
CREATE TABLE public.invitations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), team_id uuid NOT NULL REFERENCES public.teams(id), sender_id uuid NOT NULL REFERENCES public.profiles(id), recipient_id uuid NOT NULL REFERENCES public.profiles(id), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','accepted','declined')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(team_id,sender_id,recipient_id));
GRANT SELECT,INSERT,UPDATE ON public.invitations TO authenticated; GRANT ALL ON public.invitations TO service_role; ALTER TABLE public.invitations ENABLE ROW LEVEL SECURITY;
CREATE POLICY invitation_read ON public.invitations FOR SELECT TO authenticated USING(sender_id=auth.uid() OR recipient_id=auth.uid()); CREATE POLICY invitation_insert ON public.invitations FOR INSERT TO authenticated WITH CHECK(sender_id=auth.uid() AND recipient_id<>auth.uid() AND EXISTS(SELECT 1 FROM public.teams WHERE teams.id=team_id AND is_open));
CREATE TABLE public.notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id), title text NOT NULL, body text NOT NULL, read boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE ON public.notifications TO authenticated; GRANT ALL ON public.notifications TO service_role; ALTER TABLE public.notifications ENABLE ROW LEVEL SECURITY; CREATE POLICY notifications_own ON public.notifications FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.attendance(pass_id uuid PRIMARY KEY REFERENCES public.passes(id), event_id uuid NOT NULL REFERENCES public.events(id), checked_at timestamptz NOT NULL DEFAULT now(), organizer_id uuid NOT NULL REFERENCES public.profiles(id), status text NOT NULL CHECK(status IN ('present','late')), reason text NOT NULL DEFAULT '');
GRANT SELECT ON public.attendance TO authenticated; GRANT ALL ON public.attendance TO service_role; ALTER TABLE public.attendance ENABLE ROW LEVEL SECURITY; CREATE POLICY attendance_read ON public.attendance FOR SELECT TO authenticated USING(public.is_organizer() OR EXISTS(SELECT 1 FROM public.passes WHERE passes.id=pass_id AND (owner_id=auth.uid() OR lower(email)=lower(auth.jwt()->>'email'))));
CREATE TABLE public.audit_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid REFERENCES public.profiles(id), action text NOT NULL, event_id uuid REFERENCES public.events(id), details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.audit_logs TO authenticated; GRANT ALL ON public.audit_logs TO service_role; ALTER TABLE public.audit_logs ENABLE ROW LEVEL SECURITY; CREATE POLICY audit_read ON public.audit_logs FOR SELECT TO authenticated USING(public.is_organizer());
CREATE INDEX registrations_event_idx ON public.registrations(event_id); CREATE INDEX passes_owner_idx ON public.passes(owner_id); CREATE INDEX passes_email_idx ON public.passes(email); CREATE INDEX notification_user_idx ON public.notifications(user_id); CREATE INDEX attendance_event_idx ON public.attendance(event_id); CREATE INDEX teams_leader_idx ON public.teams(leader_id);
CREATE FUNCTION public.register_event(p_event uuid,p_team_name text,p_members jsonb,p_answers jsonb DEFAULT '{}') RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE ev public.events; rid uuid; tid uuid; member jsonb; n integer; emails text[]; BEGIN IF auth.uid() IS NULL OR NOT EXISTS(SELECT 1 FROM auth.users WHERE id=auth.uid() AND email_confirmed_at IS NOT NULL) THEN RAISE EXCEPTION 'Verify your email before registering'; END IF; SELECT * INTO ev FROM public.events WHERE id=p_event FOR UPDATE; IF NOT FOUND OR ev.status<>'open' OR ev.deadline<now() THEN RAISE EXCEPTION 'Registration is closed'; END IF; IF jsonb_typeof(p_members)<>'array' THEN RAISE EXCEPTION 'Invalid participants'; END IF; n:=jsonb_array_length(p_members); IF n<ev.team_min OR n>ev.team_max THEN RAISE EXCEPTION 'Invalid team size'; END IF; IF (SELECT count(*) FROM public.passes WHERE event_id=p_event AND NOT cancelled)+n>ev.capacity THEN RAISE EXCEPTION 'Not enough available places'; END IF; IF EXISTS(SELECT 1 FROM public.registrations WHERE event_id=p_event AND owner_id=auth.uid()) THEN RAISE EXCEPTION 'Already registered'; END IF; IF lower(p_members->0->>'email')<>lower(auth.jwt()->>'email') THEN RAISE EXCEPTION 'Leader email must match your verified account'; END IF; FOR member IN SELECT * FROM jsonb_array_elements(p_members) LOOP IF length(trim(member->>'name')) NOT BETWEEN 1 AND 100 OR (member->>'email') !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' OR length(member->>'email')>255 THEN RAISE EXCEPTION 'Invalid participant'; END IF; END LOOP; SELECT array_agg(lower(value->>'email')) INTO emails FROM jsonb_array_elements(p_members); IF (SELECT count(DISTINCT x) FROM unnest(emails) x)<>n THEN RAISE EXCEPTION 'Duplicate participant email'; END IF; IF n>1 THEN IF length(trim(p_team_name)) NOT BETWEEN 2 AND 80 THEN RAISE EXCEPTION 'Team name is required'; END IF; INSERT INTO public.teams(event_id,leader_id,name,is_open) VALUES(p_event,auth.uid(),trim(p_team_name),false) RETURNING id INTO tid; END IF; INSERT INTO public.registrations(event_id,owner_id,team_id,answers) VALUES(p_event,auth.uid(),tid,p_answers) RETURNING id INTO rid; FOR member IN SELECT * FROM jsonb_array_elements(p_members) LOOP INSERT INTO public.passes(registration_id,event_id,owner_id,participant,email,team_id,role) VALUES(rid,p_event,auth.uid(),trim(member->>'name'),lower(member->>'email'),tid,CASE WHEN lower(member->>'email')=lower(auth.jwt()->>'email') AND n>1 THEN 'Team leader' ELSE 'Participant' END); IF tid IS NOT NULL THEN INSERT INTO public.team_members(team_id,display_name) VALUES(tid,trim(member->>'name')); END IF; END LOOP; INSERT INTO public.notifications(user_id,title,body) VALUES(auth.uid(),'Registration confirmed',ev.title||' — your passes are ready.'); RETURN rid; END $$;
REVOKE ALL ON FUNCTION public.register_event(uuid,text,jsonb,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.register_event(uuid,text,jsonb,jsonb) TO authenticated;
CREATE FUNCTION public.check_in(p_event uuid,p_token text,p_reason text DEFAULT '') RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.passes; ev public.events; s text; BEGIN IF NOT public.is_organizer() THEN RAISE EXCEPTION 'Organizer access required'; END IF; SELECT * INTO p FROM public.passes WHERE token::text=p_token OR id::text=p_token FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Invalid pass'; END IF; IF p.event_id<>p_event THEN RAISE EXCEPTION 'This pass belongs to a different event'; END IF; IF p.cancelled THEN RAISE EXCEPTION 'Pass cancelled'; END IF; IF EXISTS(SELECT 1 FROM public.attendance WHERE pass_id=p.id) THEN RAISE EXCEPTION 'Already checked in'; END IF; SELECT * INTO ev FROM public.events WHERE id=p_event; IF ev.status='cancelled' THEN RAISE EXCEPTION 'Event cancelled'; END IF; s:=CASE WHEN now()>ev.starts_at+interval '15 minutes' THEN 'late' ELSE 'present' END; INSERT INTO public.attendance(pass_id,event_id,organizer_id,status,reason) VALUES(p.id,p_event,auth.uid(),s,left(p_reason,500)); INSERT INTO public.audit_logs(actor_id,action,event_id,details) VALUES(auth.uid(),'check_in',p_event,jsonb_build_object('pass_id',p.id,'status',s)); INSERT INTO public.notifications(user_id,title,body) VALUES(p.owner_id,'Check-in confirmed',p.participant||' checked in to '||ev.title); RETURN jsonb_build_object('name',p.participant,'status',s); END $$;
REVOKE ALL ON FUNCTION public.check_in(uuid,text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.check_in(uuid,text,text) TO authenticated;
ALTER PUBLICATION supabase_realtime ADD TABLE public.notifications;
